// Self-cleaning service worker: unregisters any old worker and cleans storage
if (typeof self !== 'undefined' && 'registration' in self) {
    self.registration.unregister().then(() => {
        console.log("Old coi-serviceworker unregistered.");
    });
}
if (typeof window !== 'undefined') {
    try {
        sessionStorage.removeItem("coiReloadedBySelf");
        sessionStorage.removeItem("coiCoepHasFailed");
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.getRegistrations().then(function(regs) {
                for (let r of regs) {
                    if (r.active && r.active.scriptURL.includes('coi-serviceworker')) {
                        r.unregister();
                    }
                }
            });
        }
    } catch(e) {}
}
